import numpy as np
from scipy.optimize import minimize

try:
    from pyDOE2 import lhs as _lhs
except ImportError:
    try:
        from scipy.stats import qmc
        def _lhs(n_samples, n_dim):
            return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
    except ImportError:
        raise ImportError("pyDOE2 or scipy required")

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.random.uniform(-1, 1, dim)
        self.rng = np.random.default_rng(42)
        self.stag = 0

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        xc = np.clip(x, -1.0, 1.0)
        f = func(xc)
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = xc.copy()
        return f

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        pop_sz = max(4, min(32, self.budget // 2))
        pop = _lhs(n_samples=pop_sz, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = min(25, max(1, self.budget // pop_sz))
        grad_w = 1.0

        for gen in range(max_gen):
            if self.evals >= self.budget: break

            valid_f = fitness[np.isfinite(fitness)]
            if len(valid_f) > 1:
                f_mean = np.mean(np.abs(valid_f)) + 1e-8
                f_std = np.std(valid_f)
                CR = np.clip(0.5 + 0.5 * (f_std / f_mean), 0.1, 0.95)
                F = np.clip(0.4 + 0.4 * (np.max(valid_f) - np.min(valid_f)) / f_mean, 0.1, 1.0)
            else:
                CR, F = 0.9, 0.8

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]

            # Gradient biasing with controlled decay
            g_bias = np.zeros(24)
            if grad_func:
                try:
                    g = grad_func(x_best)
                    if g is not None and len(g) == 18:
                        g_c = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        norm_g = np.linalg.norm(g_c) + 1e-8
                        g_bias[:18] = (g_c / norm_g) * 0.06 * grad_w
                except Exception: pass

            for i in range(pop_sz):
                if self.evals >= self.budget: break

                idxs = self.rng.choice(pop_sz, 3, replace=False)
                while np.any(idxs == i): idxs = self.rng.choice(pop_sz, 3, replace=False)

                # Dimension-aware adaptive scaling
                cat_scale = np.clip(0.12 + 0.18 * np.exp(-0.08 * (fitness[i] - fitness[best_idx])), 0.05, 0.4)
                cauchy_s = max(0.01, 0.035 * f_std / f_mean)

                v = x_best + F * (pop[idxs[0]] - pop[idxs[1]]) + g_bias
                v[:18] += cauchy_s * self.rng.standard_cauchy(18)
                v[18:] += cauchy_s * cat_scale * self.rng.standard_cauchy(6)
                v = np.clip(v, -1.0, 1.0)

                cr_mask = self.rng.random(24) < CR
                trial = np.where(cr_mask, v, pop[i])
                f_trial = self._evaluate(trial, func)

                # Gradient-guided cliff recovery
                if np.isinf(f_trial) and self.evals < self.budget:
                    jump = self.rng.normal(0, 0.05, 24)
                    jump[18:] *= cat_scale
                    if grad_func:
                        try:
                            g = grad_func(trial)
                            if g is not None: jump[:18] += 0.12 * np.nan_to_num(g[:18])
                        except Exception: pass
                    trial_j = np.clip(trial + jump, -1.0, 1.0)
                    f_trial = self._evaluate(trial_j, func)

                if f_trial < fitness[i]:
                    pop[i] = trial
                    fitness[i] = f_trial
                else:
                    self.stag += 1

            if self.stag > 18:
                self.stag = 0
                pop += self.rng.normal(0, 0.11, (pop_sz, 24))
                pop = np.clip(pop, -1.0, 1.0)
                fitness = np.array([self._evaluate(p, func) for p in pop])

            grad_w *= 0.99

        # High-resolution refinement phase
        if self.evals < self.budget and grad_func:
            n_ref = min(5, pop_sz)
            top_idx = np.argsort(fitness)[:n_ref]
            grad_w = 1.0

            for idx in top_idx:
                if self.evals >= self.budget * 0.95: break
                x0 = pop[idx]
                cats = x0[18:]
                cont = x0[:18]

                def cost_wrap(x_c): 
                    return self._evaluate(np.concatenate([x_c, cats]), func)

                def grad_wrap(x_c):
                    full = np.concatenate([x_c, cats])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception:
                        return np.zeros(18)

                res = minimize(cost_wrap, cont, jac=grad_wrap, method='L-BFGS-B', 
                               bounds=[(-1.0, 1.0)]*18, 
                               options={'maxiter': 150, 'ftol': 1e-8, 'gtol': 1e-7})

                if np.isfinite(res.fun) and res.fun < self.best_f:
                    self.best_f = res.fun
                    self.best_x = np.concatenate([res.x, cats])

        return self.best_f, self.best_x
